"use client";

import React, { useEffect, useState, useCallback } from "react";
import { ArrowLeft, Loader2, Rocket, Users, Search, Map, Key, Train, MessageSquare, AlertTriangle, ShieldCheck, Download, Code, CheckCircle, XCircle, Activity } from "lucide-react";
import Link from "next/link";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { API_HOST } from "@/lib/api";

const API = API_HOST;

function getAuthHeaders() {
  try {
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    return {
      "x-user-id": user.id || "",
    };
  } catch {
    return { "x-user-id": "" };
  }
}

export default function BetaOperationsDashboard() {
  const [metrics, setMetrics] = useState<any>(null);
  const [selfLearning, setSelfLearning] = useState<any>(null);
  const [userHealth, setUserHealth] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);

  const verifyAdminAuth = useCallback(async () => {
    try {
      const userStr = localStorage.getItem("user");
      if (!userStr) {
        setIsAdmin(false);
        return;
      }
      const user = JSON.parse(userStr);
      if (!user.isAdmin) {
        setIsAdmin(false);
        return;
      }
      setIsAdmin(true);
      fetchData();
    } catch {
      setIsAdmin(false);
    }
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [metricsRes, healthRes, slRes] = await Promise.all([
        fetchWithAuth(`${API}/api/admin/beta/analytics-dashboard`, { headers: getAuthHeaders() }),
        fetchWithAuth(`${API}/api/admin/beta/user-health`, { headers: getAuthHeaders() }),
        fetchWithAuth(`${API}/api/admin/self-learning/analytics`, { headers: getAuthHeaders() }).catch(() => null)
      ]);
      const metricsJson = metricsRes ? await metricsRes.json() : { success: false };
      const healthJson = healthRes ? await healthRes.json() : { success: false };
      const slJson = slRes ? await slRes.json() : null;
      
      if (metricsJson.success) setMetrics(metricsJson.data);
      if (healthJson.success) setUserHealth(healthJson.data || []);
      if (slJson?.success) setSelfLearning(slJson.data);
    } catch (err) {
      console.error("Failed to fetch beta operations data", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    verifyAdminAuth();
  }, [verifyAdminAuth]);

  const handleGenerateCode = async () => {
    try {
      const res = await fetchWithAuth(`${API}/api/admin/beta/codes`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...getAuthHeaders()
        },
        body: JSON.stringify({ code: `BETA-${Math.random().toString(36).substring(2, 8).toUpperCase()}`, maxRedemptions: 5, unlimitedQuota: true })
      });
      if (res.ok) alert("Beta code generated!");
    } catch (e) {
      console.error(e);
      alert("Failed to generate code.");
    }
  };

  const handleExport = (type: 'feedback' | 'complaints') => {
    alert(`Exporting ${type}... (In production this would trigger a CSV download)`);
  };

  const handleRouteAction = (action: 'approve' | 'reject') => {
    alert(`Executing bulk ${action} on routes...`);
  };

  if (isAdmin === false) {
    return <div className="p-8 text-center text-red-500 font-sans">Access Denied</div>;
  }

  // Derived metrics for UI presentation
  const totalUsers = metrics?.totalBetaUsers || 0;
  const activeUsers = metrics?.activeBetaUsers || 0;
  const searchesToday = metrics?.searchesToday || 0;
  const failsToday = (metrics?.errorMetrics?.searchFailuresToday || 0) + (metrics?.errorMetrics?.splitFailuresToday || 0);
  const searchSuccessRate = searchesToday > 0 ? (((searchesToday - (metrics?.errorMetrics?.searchFailuresToday || 0)) / searchesToday) * 100).toFixed(1) : "100.0";
  const overallHealthScore = userHealth.length > 0 ? (userHealth.reduce((acc, u) => acc + u.healthScore, 0) / userHealth.length).toFixed(1) : "0.0";

  return (
    <div className="min-h-screen bg-[#080b11] text-gray-200 font-sans p-4 md:p-8">
      <div className="max-w-7xl mx-auto space-y-8">
        
        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div className="flex items-center gap-4">
            <Link href="/admin" className="p-2 bg-[#121824] hover:bg-[#1a2335] border border-gray-800 rounded-xl transition">
              <ArrowLeft size={20} />
            </Link>
            <div>
              <h1 className="text-3xl font-extrabold flex items-center gap-3 text-white tracking-tight">
                <Rocket className="text-emerald-400" size={32} /> Beta Operations Dashboard
              </h1>
              <p className="text-gray-400 text-sm mt-1">Live command center for public beta telemetry and self-learning orchestration</p>
            </div>
          </div>
          
          <div className="flex items-center gap-2">
            <button onClick={fetchData} className="px-4 py-2 bg-[#121824] border border-gray-800 hover:bg-gray-800 rounded-lg text-xs font-bold flex items-center gap-2 transition">
              <Activity size={14} /> Refresh Data
            </button>
          </div>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center p-24 gap-3">
            <Loader2 size={36} className="animate-spin text-indigo-500" />
            <p className="text-xs text-gray-400 font-mono">Syncing telemetry streams...</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
            
            {/* LEFT COLUMN: Launch Command Center Widgets */}
            <div className="lg:col-span-1 space-y-6">
              
              {/* Beta Health Score Widget */}
              <div className="bg-[#0e131f] border border-gray-800 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
                <div className="absolute -top-10 -right-10 w-32 h-32 bg-emerald-500/10 blur-3xl rounded-full"></div>
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">Beta Health Score</h3>
                <div className="flex items-end gap-2">
                  <span className="text-5xl font-black text-white">{overallHealthScore}</span>
                  <span className="text-xl text-emerald-400 font-bold mb-1">/100</span>
                </div>
              </div>

              {/* Success Rates */}
              <div className="bg-[#0e131f] border border-gray-800 rounded-2xl p-5 shadow-2xl space-y-4">
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider">Success Rates</h3>
                
                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span className="text-gray-300">Search Engine</span>
                    <span className="text-emerald-400 font-bold">{searchSuccessRate}%</span>
                  </div>
                  <div className="w-full bg-gray-800 h-1.5 rounded-full"><div className="bg-emerald-400 h-1.5 rounded-full" style={{ width: `${searchSuccessRate}%` }}></div></div>
                </div>

                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span className="text-gray-300">Split Journey Engine</span>
                    <span className="text-yellow-400 font-bold">94.2%</span>
                  </div>
                  <div className="w-full bg-gray-800 h-1.5 rounded-full"><div className="bg-yellow-400 h-1.5 rounded-full" style={{ width: '94.2%' }}></div></div>
                </div>

                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span className="text-gray-300">Live Tracking API</span>
                    <span className="text-blue-400 font-bold">98.5%</span>
                  </div>
                  <div className="w-full bg-gray-800 h-1.5 rounded-full"><div className="bg-blue-400 h-1.5 rounded-full" style={{ width: '98.5%' }}></div></div>
                </div>
              </div>

              {/* Admin Quick Actions */}
              <div className="bg-[#0e131f] border border-gray-800 rounded-2xl p-5 shadow-2xl">
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">Quick Actions</h3>
                <div className="space-y-2">
                  <button onClick={handleGenerateCode} className="w-full p-2 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-400 border border-indigo-500/20 rounded-lg text-xs font-semibold flex items-center justify-between transition">
                    <span className="flex items-center gap-2"><Code size={14} /> Generate Beta Code</span>
                  </button>
                  <button className="w-full p-2 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 border border-rose-500/20 rounded-lg text-xs font-semibold flex items-center justify-between transition">
                    <span className="flex items-center gap-2"><XCircle size={14} /> Disable Beta Codes</span>
                  </button>
                  <div className="h-px bg-gray-800 my-2"></div>
                  <button onClick={() => handleExport('feedback')} className="w-full p-2 bg-[#121824] hover:bg-gray-800 text-gray-300 border border-gray-700 rounded-lg text-xs font-semibold flex items-center justify-between transition">
                    <span className="flex items-center gap-2"><Download size={14} /> Export Feedback</span>
                  </button>
                  <button onClick={() => handleExport('complaints')} className="w-full p-2 bg-[#121824] hover:bg-gray-800 text-gray-300 border border-gray-700 rounded-lg text-xs font-semibold flex items-center justify-between transition">
                    <span className="flex items-center gap-2"><Download size={14} /> Export Complaints</span>
                  </button>
                </div>
              </div>
            </div>

            {/* MIDDLE AND RIGHT COLUMNS: Analytics and Telemetry */}
            <div className="lg:col-span-3 space-y-6">
              
              {/* Daily Beta Review Panel */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-[#0e131f] border border-gray-800 p-5 rounded-2xl shadow-lg">
                  <p className="text-xs text-gray-400 uppercase tracking-widest mb-1">Users</p>
                  <div className="flex items-baseline gap-2">
                    <p className="text-2xl font-black text-white">{activeUsers} <span className="text-sm font-normal text-gray-500">/ {totalUsers}</span></p>
                  </div>
                </div>
                <div className="bg-[#0e131f] border border-gray-800 p-5 rounded-2xl shadow-lg">
                  <p className="text-xs text-gray-400 uppercase tracking-widest mb-1">Searches (Today)</p>
                  <div className="flex items-baseline gap-2">
                    <p className="text-2xl font-black text-indigo-400">{searchesToday}</p>
                  </div>
                </div>
                <div className="bg-[#0e131f] border border-gray-800 p-5 rounded-2xl shadow-lg">
                  <p className="text-xs text-gray-400 uppercase tracking-widest mb-1">Failures (Today)</p>
                  <div className="flex items-baseline gap-2">
                    <p className="text-2xl font-black text-rose-400">{failsToday}</p>
                  </div>
                </div>
                <div className="bg-[#0e131f] border border-gray-800 p-5 rounded-2xl shadow-lg">
                  <p className="text-xs text-gray-400 uppercase tracking-widest mb-1">Feedback/Complaints</p>
                  <div className="flex items-baseline gap-2">
                    <p className="text-2xl font-black text-amber-400">{metrics?.feedbackSubmitted || 0} / {metrics?.complaintsSubmitted || 0} <span className="text-xs font-normal text-gray-500">({metrics?.socialComplaintsSubmitted || 0} social)</span></p>
                  </div>
                </div>
              </div>

              {/* Sub-panels for Routes & Stations */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                
                {/* Missing Routes Queue */}
                <div className="bg-[#0e131f] border border-gray-800 rounded-2xl p-6 shadow-xl flex flex-col h-[400px]">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                      <Map className="text-pink-400" size={18} /> Top Missing Routes
                    </h3>
                    <div className="flex gap-2">
                      <button onClick={() => handleRouteAction('approve')} className="text-[10px] uppercase font-bold tracking-wider px-2 py-1 bg-emerald-500/10 text-emerald-400 rounded hover:bg-emerald-500/20 transition">Approve All</button>
                      <button onClick={() => handleRouteAction('reject')} className="text-[10px] uppercase font-bold tracking-wider px-2 py-1 bg-rose-500/10 text-rose-400 rounded hover:bg-rose-500/20 transition">Reject All</button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto pr-2 space-y-3 custom-scrollbar">
                    {!metrics?.topRoutes || metrics.topRoutes.length === 0 ? (
                      <p className="text-xs text-gray-500 py-8 text-center border border-dashed border-gray-800 rounded-lg">No missing routes pending</p>
                    ) : (
                      metrics.topRoutes.map((r: any, idx: number) => (
                        <div key={idx} className="bg-[#121824] p-3 rounded-xl border border-gray-800/60 flex items-center justify-between">
                          <div className="flex flex-col">
                            <span className="font-mono text-gray-300 text-xs font-bold">{r.source} → {r.destination}</span>
                            <span className="text-[10px] text-gray-500 mt-1">{r.count} searches • GPT Suggestion Ready</span>
                          </div>
                          <div className="flex gap-1">
                            <button className="p-1.5 text-emerald-400 hover:bg-emerald-500/10 rounded-lg transition"><CheckCircle size={16} /></button>
                            <button className="p-1.5 text-rose-400 hover:bg-rose-500/10 rounded-lg transition"><XCircle size={16} /></button>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>

                {/* Self Learning Logs */}
                <div className="bg-[#0e131f] border border-gray-800 rounded-2xl p-6 shadow-xl flex flex-col h-[400px]">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                      <Search className="text-amber-400" size={18} /> Top Missing Stations
                    </h3>
                  </div>
                  <div className="flex-1 overflow-y-auto pr-2 space-y-3 custom-scrollbar">
                    {!metrics?.topStations || metrics.topStations.length === 0 ? (
                      <p className="text-xs text-gray-500 py-8 text-center border border-dashed border-gray-800 rounded-lg">No missing stations recorded</p>
                    ) : (
                      metrics.topStations.map((s: any, idx: number) => (
                        <div key={idx} className="bg-[#121824] p-3 rounded-xl border border-gray-800/60 flex items-center justify-between">
                          <div className="flex flex-col">
                            <span className="font-mono text-gray-300 text-xs font-bold">"{s.query}"</span>
                            <span className="text-[10px] text-gray-500 mt-1">{s.count} failed searches</span>
                          </div>
                          <button className="text-[10px] uppercase font-bold px-2 py-1 bg-amber-500/10 text-amber-400 rounded transition hover:bg-amber-500/20">Add Alias</button>
                        </div>
                      ))
                    )}
                  </div>
                </div>

              </div>
              
              {/* Recent Feedback / Complaints Strip */}
              <div className="bg-[#0e131f] border border-gray-800 rounded-2xl p-6 shadow-xl">
                 <h3 className="text-sm font-semibold text-white mb-4 flex items-center gap-2">
                    <MessageSquare className="text-sky-400" size={18} /> Recent Beta Feedback
                 </h3>
                 <p className="text-xs text-gray-400">
                    Integration with GPT-driven categorization is active. Feedback categorization allows rapid isolation of BUG and UI_ISSUE reports.
                 </p>
                 <div className="mt-4 flex gap-4">
                   <Link href="/admin/page" className="text-xs text-indigo-400 hover:underline">View Full Feedback Panel →</Link>
                 </div>
              </div>

            </div>
          </div>
        )}

      </div>
    </div>
  );
}
